--
-- Table structure for table `global_equipment`
--

DROP TABLE IF EXISTS `global_equipment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `global_equipment` (
  `item_barcode` varchar(50) NOT NULL,
  `item_type` varchar(50) NOT NULL,
  `brand_model` varchar(80) NOT NULL,
  `purchase_date` date NOT NULL,
  `unit_cost_usd` decimal(8,2) NOT NULL,
  `current_status` varchar(30) NOT NULL,
  `school_id` int DEFAULT NULL,
  `shipping_date` date DEFAULT NULL,
  PRIMARY KEY (`item_barcode`),
  KEY `fk_equipment_school` (`school_id`),
  CONSTRAINT `fk_equipment_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`school_id`),
  CONSTRAINT `chk_cost_positive` CHECK ((`unit_cost_usd` >= 0)),
  CONSTRAINT `chk_equipment_status` CHECK ((`current_status` in (_utf8mb4'In Central Warehouse',_utf8mb4'In Use',_utf8mb4'Lost',_utf8mb4'Damaged/Scrapped'))),
  CONSTRAINT `chk_item_type` CHECK ((`item_type` in (_utf8mb4'Match Ball',_utf8mb4'Training Ball',_utf8mb4'Cones Set',_utf8mb4'Goal Net',_utf8mb4'Match Jersey',_utf8mb4'Training Bibs'))),
  CONSTRAINT `chk_shipping_date` CHECK (((`shipping_date` is null) or (`shipping_date` >= `purchase_date`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

